//! 🔣️ Rewriting declared JSON maps only real owner scalar roles into closed word and property variants.
use semio_framework_value::DslValue;
use semio_framework_value::ValueError;
use semio_framework_value::ValueRefusalKind;
fn invalid(message:&str)->ValueError{semio_framework_value::ValueError::new(ValueRefusalKind::InvalidValue,message)}
fn fields(value:&mut DslValue)->Result<&mut Vec<(String,DslValue)>,ValueError>{match value{semio_framework_value::DslValue::Object(fields)=>Ok(fields),_=>Err(invalid("Rewriting JSON object required"))}}
fn take(value:&mut DslValue,key:&str)->Result<DslValue,ValueError>{fields(value)?.iter_mut().find(|(name,_)|name==key).map(|(_,value)|std::mem::replace(value,semio_framework_value::DslValue::Null)).ok_or_else(||invalid("Rewriting JSON declared field missing"))}
fn word(value:DslValue,decode:bool)->Result<DslValue,ValueError>{if decode{let semio_framework_value::DslValue::Object(entries)=value else{return Err(invalid("Rewriting JSON binary64 word required"))};if entries.len()!=1||entries[0].0!="bits"{return Err(invalid("Rewriting JSON binary64 fields"))}let bits=entries[0].1.as_str().ok_or_else(||invalid("Rewriting JSON word text required"))?;if bits.len()!=16||!bits.bytes().all(|byte|byte.is_ascii_digit()||(b'a'..=b'f').contains(&byte)){return Err(invalid("Rewriting JSON lowercase hex64 required"))}Ok(semio_framework_value::DslValue::float(f64::from_bits(u64::from_str_radix(bits,16).map_err(|_|invalid("Rewriting JSON hex64 invalid"))?)))}else{let bits=value.as_f64().ok_or_else(||invalid("Rewriting owned binary64 required"))?.to_bits();Ok(semio_framework_value::DslValue::object([("bits".into(),semio_framework_value::DslValue::String(format!("{bits:016x}")))]))}}
fn property(mut value:DslValue,decode:bool)->Result<DslValue,ValueError>{if decode{let kind=take(&mut value,"kind")?;let kind=kind.as_str().ok_or_else(||invalid("Rewriting property kind text required"))?;let expected=if kind=="null"{1}else{2};if fields(&mut value)?.len()!=expected{return Err(invalid("Rewriting property closed fields required"))}match kind{"null"=>Ok(semio_framework_value::DslValue::Null),"bool"=>{let value=take(&mut value,"value")?;if !matches!(value,DslValue::Bool(_)){return Err(invalid("Rewriting property bool required"))}Ok(value)},"number"=>word(take(&mut value,"value")?,true),"string"=>{let value=take(&mut value,"value")?;if !matches!(value,DslValue::String(_)){return Err(invalid("Rewriting property string required"))}Ok(value)},"array"=>{let semio_framework_value::DslValue::Array(values)=take(&mut value,"values")? else{return Err(invalid("Rewriting property array required"))};Ok(semio_framework_value::DslValue::Array(values.into_iter().map(|value|property(value,true)).collect::<Result<_,_>>()?))},"object"=>{let semio_framework_value::DslValue::Object(values)=take(&mut value,"values")? else{return Err(invalid("Rewriting property members required"))};Ok(semio_framework_value::DslValue::Object(values.into_iter().map(|(key,value)|property(value,true).map(|value|(key,value))).collect::<Result<_,_>>()?))},_=>Err(invalid("Rewriting property kind unknown"))}}else{let(kind,key,value)=match value{semio_framework_value::DslValue::Null=>return Ok(semio_framework_value::DslValue::object([("kind".into(),semio_framework_value::DslValue::String("null".into()))])),semio_framework_value::DslValue::Bool(value)=>("bool","value",semio_framework_value::DslValue::Bool(value)),semio_framework_value::DslValue::Number(value)=>("number","value",word(semio_framework_value::DslValue::Number(value),false)?),semio_framework_value::DslValue::String(value)=>("string","value",semio_framework_value::DslValue::String(value)),semio_framework_value::DslValue::Array(values)=>("array","values",semio_framework_value::DslValue::Array(values.into_iter().map(|value|property(value,false)).collect::<Result<_,_>>()?)),semio_framework_value::DslValue::Object(values)=>("object","values",semio_framework_value::DslValue::Object(values.into_iter().map(|(key,value)|property(value,false).map(|value|(key,value))).collect::<Result<_,_>>()?)),semio_framework_value::DslValue::Bytes(_)=>return Err(invalid("Rewriting property cannot own intrinsic bytes"))};Ok(semio_framework_value::DslValue::object([("kind".into(),semio_framework_value::DslValue::String(kind.into())),(key.into(),value)]))}}
fn member_property(value:&mut DslValue,key:&str,decode:bool)->Result<(),ValueError>{let member=fields(value)?.iter_mut().find(|(name,_)|name==key).ok_or_else(||invalid("Rewriting property role missing"))?;member.1=property(std::mem::replace(&mut member.1,semio_framework_value::DslValue::Null),decode)?;Ok(())}
pub fn rhs(mut value:DslValue,decode:bool)->Result<DslValue,ValueError>{for(name,role)in[("set","value"),("parameters","default")]{let members=fields(&mut value)?.iter_mut().find(|(key,_)|key==name).ok_or_else(||invalid("Rewriting RHS declared list missing"))?;let semio_framework_value::DslValue::Array(items)=&mut members.1 else{return Err(invalid("Rewriting RHS list required"))};for item in items{member_property(item,role,decode)?;}}Ok(value)}
fn member<'a>(value:&'a mut DslValue,key:&str)->Result<&'a mut DslValue,ValueError>{fields(value)?.iter_mut().find(|(name,_)|name==key).map(|(_,value)|value).ok_or_else(||invalid("Rewriting declared role missing"))}
fn axes(value:&mut DslValue,decode:bool)->Result<(),ValueError>{let axes=fields(value)?;if axes.len()!=2||axes.iter().any(|(axis,_)|axis!="x"&&axis!="y"){return Err(invalid("Rewriting layout fields"))}for(_,axis)in axes{*axis=word(std::mem::replace(axis,semio_framework_value::DslValue::Null),decode)?;}Ok(())}
fn jack(value:&mut DslValue,decode:bool)->Result<(),ValueError>{let camera=fields(member(value,"camera")?)?;if camera.len()!=3||camera.iter().any(|(key,_)|!["x","y","zoom"].contains(&key.as_str())){return Err(invalid("Rewriting Jack camera fields"))}for(_,axis)in camera{*axis=word(std::mem::replace(axis,semio_framework_value::DslValue::Null),decode)?;}Ok(())}
pub fn mutation(mut value:DslValue,decode:bool)->Result<DslValue,ValueError>{
 let kind=member(&mut value,"mutation")?.as_str().ok_or_else(||invalid("Rewriting mutation discriminator required"))?.to_owned();
 let roles:&[&str]=match kind.as_str(){"editLhs"=>&["newLhs"],"editRhs"=>&["newRhs"],"editWorkingGraph"=>&["newWorkingGraph"],"changeParameterBinding"=>&["key","newValue"],"removeParameterBinding"|"removeRuleLayoutPoint"=>&["key"],"changeRuleLayoutPoint"=>&["key","newPoint"],"dragRuleNodes"=>&["targets","dx","dy"],"setRuleLayoutPoints"=>&["points","cleared"],_=>return Err(invalid("Rewriting mutation discriminator unknown"))};
 let root=fields(&mut value)?;if root.len()!=roles.len()+1||root.iter().any(|(key,_)|key!="mutation"&&!roles.contains(&key.as_str())){return Err(invalid("Rewriting mutation closed fields required"))}
 match kind.as_str(){"editRhs"=>{let item=member(&mut value,"newRhs")?;*item=rhs(std::mem::replace(item,semio_framework_value::DslValue::Null),decode)?;},"editWorkingGraph"=>jack(member(&mut value,"newWorkingGraph")?,decode)?,"changeParameterBinding"=>member_property(&mut value,"newValue",decode)?,"changeRuleLayoutPoint"=>axes(member(&mut value,"newPoint")?,decode)?,"dragRuleNodes"=>{for key in["dx","dy"]{let axis=member(&mut value,key)?;*axis=word(std::mem::replace(axis,semio_framework_value::DslValue::Null),decode)?;}},"setRuleLayoutPoints"=>{let semio_framework_value::DslValue::Array(points)=member(&mut value,"points")? else{return Err(invalid("Rewriting layout points required"))};for point in points{let point_fields=fields(point)?;if point_fields.len()!=3||point_fields.iter().any(|(key,_)|!["key","x","y"].contains(&key.as_str())){return Err(invalid("Rewriting placement fields"))}for key in["x","y"]{let axis=member(point,key)?;*axis=word(std::mem::replace(axis,semio_framework_value::DslValue::Null),decode)?;}}},_=>{}}Ok(value)
}
pub fn diff(mut value:DslValue,decode:bool)->Result<DslValue,ValueError>{
 let root=fields(&mut value)?;if root.iter().any(|(key,_)|!["workingGraph","lhs","rhs","parameterBindings","ruleLayout"].contains(&key.as_str())){return Err(invalid("Rewriting diff closed fields required"))}
 for(key,value)in root{if matches!(value,DslValue::Null){continue}match key.as_str(){"workingGraph"=>jack(value,decode)?,"rhs"=>*value=rhs(std::mem::replace(value,semio_framework_value::DslValue::Null),decode)?,"parameterBindings"|"ruleLayout"=>{let semio_framework_value::DslValue::Array(entries)=member(value,"entries")? else{return Err(invalid("Rewriting map delta entries required"))};for entry in entries{let operation=member(entry,"operation")?;let kind=member(operation,"kind")?.as_str().ok_or_else(||invalid("Rewriting map delta operation required"))?;if kind=="set"{if key=="parameterBindings"{member_property(operation,"value",decode)?}else{axes(member(operation,"value")?,decode)?}}}},_=>{}}}Ok(value)
}
pub fn convert(mut value:DslValue,decode:bool)->Result<DslValue,ValueError>{
 let root=fields(&mut value)?;if root.len()!=5||root.iter().any(|(key,_)|!["workingGraph","lhs","rhs","parameterBindings","ruleLayout"].contains(&key.as_str())){return Err(invalid("Rewriting declared JSON closed parent fields required"))}
 for(key,value)in root{match key.as_str(){"workingGraph"=>{let camera=fields(value)?.iter_mut().find(|(name,_)|name=="camera").ok_or_else(||invalid("Rewriting Jack camera missing"))?;for(key,axis)in fields(&mut camera.1)?{if !["x","y","zoom"].contains(&key.as_str()){return Err(invalid("Rewriting Jack camera fields"))}*axis=word(std::mem::replace(axis,semio_framework_value::DslValue::Null),decode)?;}},"rhs"=>*value=rhs(std::mem::replace(value,semio_framework_value::DslValue::Null),decode)?,"parameterBindings"=>{for(_,value)in fields(value)?{*value=property(std::mem::replace(value,semio_framework_value::DslValue::Null),decode)?;}},"ruleLayout"=>{for(_,point)in fields(value)?{let axes=fields(point)?;if axes.len()!=2||axes.iter().any(|(axis,_)|axis!="x"&&axis!="y"){return Err(invalid("Rewriting layout fields"))}for(_,axis)in axes{*axis=word(std::mem::replace(axis,semio_framework_value::DslValue::Null),decode)?;}}},_=>{}}}Ok(value)
}
